async function main() {
  console.log('Adding exercises for Chapters 28-29...\n');
  
  for (const [slug, exercises] of Object.entries(exercisesByLesson)) {
    const lesson = await prisma.lesson.findUnique({
      where: { slug },
      include: { exercises: true }
    });
    
    if (!lesson) {
      console.log(`⚠️  Lesson not found: ${slug}`);
      continue;
    }
    
    const existingCount = lesson.exercises.length;
    if (existingCount >= 10) {
      console.log(`✓ ${slug}: already has ${existingCount} exercises`);
      continue;
    }
    
    if (existingCount > 0) {
      await prisma.exercise.deleteMany({ where: { lessonId: lesson.id } });
    }
    
    let order = 1;
    for (const ex of exercises) {
      await prisma.exercise.create({
        data: {
          lessonId: lesson.id,
          number: order,
          title: ex.title,
          prompt: ex.prompt,
          type: ex.type || 'CODE',
          difficulty: ex.difficulty || 'BEGINNER',
          xpReward: ex.xpReward || 10,
          starterCode: ex.starterCode || null,
          solution: ex.solution || null,
          hints: ex.hints || [],
          order: order,
        }
      });
      order++;
    }
    
    console.log(`✓ ${slug}: created ${exercises.length} exercises`);
  }
  
  console.log('\nDone!');
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect());
